package fr.formation.hexagonal.adapter.in.web;
import fr.formation.hexagonal.application.port.in.ManageRoomUseCase; import fr.formation.hexagonal.domain.Room; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/rooms") class RoomWebAdapter { private final ManageRoomUseCase rooms; RoomWebAdapter(ManageRoomUseCase rooms){this.rooms=rooms;} @PostMapping @ResponseStatus(HttpStatus.CREATED) Room create(@RequestBody Request r){return rooms.create(r.name(),r.capacity());} @GetMapping List<Room> list(){return rooms.list();} record Request(String name,int capacity){} }
